CREATE TABLE admins (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL, password_hash TEXT NOT NULL, token_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE settings (id INTEGER PRIMARY KEY AUTOINCREMENT, server_public_key TEXT, server_private_key TEXT, endpoint TEXT, listen_port INTEGER, wg_subnet TEXT, hub_ip TEXT, dns_ip TEXT, dns_suffix TEXT, mtu INTEGER, status_interval INTEGER, upstream_dns TEXT);
CREATE TABLE peers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, public_key TEXT NOT NULL, private_key TEXT NOT NULL, wg_ip TEXT NOT NULL, group_id INTEGER, enabled INTEGER DEFAULT 1, dns_name TEXT, last_handshake INTEGER, rx_bytes INTEGER, tx_bytes INTEGER, created_at DATETIME);
CREATE TABLE peer_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, pos_x REAL, pos_y REAL, allow_intra_group INTEGER NOT NULL DEFAULT 1, passive INTEGER);
CREATE TABLE group_links (id INTEGER PRIMARY KEY AUTOINCREMENT, from_group_id INTEGER NOT NULL, to_group_id INTEGER NOT NULL, bidirectional INTEGER NOT NULL);
CREATE TABLE dns_records (id INTEGER PRIMARY KEY AUTOINCREMENT, hostname TEXT NOT NULL, ip TEXT NOT NULL, peer_id INTEGER, manual INTEGER);
CREATE TABLE port_forwards (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, listen_port INTEGER NOT NULL, protocol TEXT NOT NULL, target_host TEXT NOT NULL, target_port INTEGER NOT NULL);
CREATE TABLE service_relays (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, slug TEXT NOT NULL, target_host TEXT NOT NULL, virtual_ip TEXT NOT NULL);
CREATE TABLE relay_group_allows (relay_id INTEGER NOT NULL, group_id INTEGER NOT NULL);
CREATE TABLE port_forward_dmzs (id INTEGER PRIMARY KEY AUTOINCREMENT, target_host TEXT);
